  async function uploadPdfCloud(path,file,onProgress=()=>{}){if(file.size<=6*1024*1024){const {error}=await cloudClient.storage.from('book-files').upload(path,file,{contentType:'application/pdf',upsert:false});if(error)throw error;return}const Upload=window.tus?.Upload;if(!Upload)throw new Error('The resumable upload library did not load. Refresh the page and try again.');const {data:{session}}=await cloudClient.auth.getSession();if(!session?.access_token)throw new Error('Your sign-in expired. Log in again and retry the upload.');const projectId=new URL(window.STACKS_CONFIG.supabaseUrl).hostname.split('.')[0];await new Promise((resolve,reject)=>{const upload=new Upload(file,{endpoint:`https://${projectId}.storage.supabase.co/storage/v1/upload/resumable`,retryDelays:[0,3000,5000,10000,20000],fingerprint:()=>Promise.resolve(`stacks:${path}:${file.size}`),headers:{authorization:`Bearer ${session.access_token}`},uploadDataDuringCreation:true,removeFingerprintOnSuccess:true,metadata:{bucketName:'book-files',objectName:path,contentType:'application/pdf',cacheControl:'3600'},chunkSize:6*1024*1024,onError:reject,onProgress:(sent,total)=>onProgress(Math.round(sent*100/total)),onSuccess:resolve});void upload.findPreviousUploads().then(previous=>{if(previous.length)upload.resumeFromPreviousUpload(previous[0]);upload.start()}).catch(reject)})}
  async function saveBookToCloud(book,files,cover,pageCounts){const user=currentUser;if(!cloudClient||!user)throw new Error('Sign in with a configured account before uploading a book.');const db=cloudClient,paths=[];const coverPath=cover?`${user.id}/${book.id}/${crypto.randomUUID()}-${cover.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`:null;let rowCreated=false;try{const {error}=await db.from('books').insert({id:book.id,owner_id:user.id,title:book.title,author:book.author,pages:book.pages,is_published:book.isPublished,cover_path:coverPath});if(error)throw error;rowCreated=true;if(coverPath){const {error:coverError}=await db.storage.from('book-covers').upload(coverPath,cover,{contentType:cover.type,upsert:false});if(coverError)throw coverError}const chapters=[];for(let i=0;i<files.length;i++){const file=files[i],path=`${user.id}/${book.id}/${String(i+1).padStart(2,'0')}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;await uploadPdfCloud(path,file,percent=>{const status=document.querySelector('#uploadStatus');if(status)status.textContent=`Uploading PDF ${i+1} of ${files.length} · ${percent}%`});paths.push(path);chapters.push({book_id:book.id,owner_id:user.id,position:i,file_name:file.name,object_path:path,page_count:pageCounts[i]})}const {error:chapterError}=await db.from('book_chapters').insert(chapters);if(chapterError)throw chapterError;return true}catch(error){if(paths.length)await db.storage.from('book-files').remove(paths);if(coverPath)await db.storage.from('book-covers').remove([coverPath]);if(rowCreated)await db.from('books').delete().eq('id',book.id);throw error}}
