  async function loadCloudBooks(){if(!cloudClient)return;for(let i=catalog.length-1;i>=0;i--){if(catalog[i].cloudId){uploadedBooks.delete(catalog[i].cloudId);catalog.splice(i,1)}}let ownIds=new Set();if(currentUser){const {data:owned}=await cloudClient.rpc('my_book_ids');ownIds=new Set((owned||[]).map(row=>row.book_id))}const {data,error}=await cloudClient.from('books').select('id,title,author,pages,cover_path,is_published,created_at').order('created_at',{ascending:false}).limit(200);if(error){console.warn('Could not load shared books:',error.message);return}const ids=(data||[]).map(book=>book.id),chaptersByBook=new Map();if(ids.length){const {data:chapters}=await cloudClient.from('book_chapters').select('*').in('book_id',ids).order('position');for(const chapter of chapters||[]){if(!chaptersByBook.has(chapter.book_id))chaptersByBook.set(chapter.book_id,[]);chaptersByBook.get(chapter.book_id).push(chapter)}}for(const book of data||[]){let coverUrl='';if(book.cover_path){const {data:coverData}=await cloudClient.storage.from('book-covers').createSignedUrl(book.cover_path,3600);coverUrl=coverData?.signedUrl||''}const card={id:book.id,cloudId:book.id,title:book.title,author:book.author,genre:'Community books',pages:book.pages,rating:0,available:true,ebook:true,mood:[],color:'#536f61',words:[],source:'cloud',ownerId:ownIds.has(book.id)?currentUser.id:null,isPublished:book.is_published,coverDataUrl:coverUrl};uploadedBooks.set(book.id,{...card,pdfs:chaptersByBook.get(book.id)||[]});const index=catalog.findIndex(item=>item.cloudId===book.id||item.uploadId===book.id);if(index>=0)catalog[index]=card;else catalog.push(card)}updatePageFilterMax();for(const book of catalog.filter(item=>item.cloudId&&item.isPublished))updatePublicBookSEO(book);render()}
