  function score(b){let n=0;state.moods.forEach(m=>{if(b.mood.includes(m))n+=3});const g=$('#genre').value;if(g&&b.genre===g)n+=5;if(profile.genre&&b.genre===profile.genre)n+=3;if(profile.maxPages)n+=b.pages<=profile.maxPages?2:-1;if(state.query){const q=state.query.toLowerCase();const text=[b.title,b.author,b.genre,...b.words].join(' ').toLowerCase();if(text.includes(q))n+=8;else n+=b.words.some(w=>q.split(/\s+/).some(t=>w.includes(t)))?2:0}if(state.guideMode){const p=state.guidePreferences;if(p.mood&&b.mood.includes(p.mood))n+=4;if(p.genre&&b.genre===p.genre)n+=6;if(p.text){const terms=p.text.toLowerCase().split(/[^a-z0-9]+/).filter(w=>w.length>2);const text=[b.title,b.author,b.genre,...b.words].join(' ').toLowerCase();n+=terms.reduce((sum,t)=>sum+(text.includes(t)?2:0),0)}}if(feedback[b.title]==='like')n+=5;if(feedback[b.title]==='skip')n-=5;if(b.available)n+=.3;return n}
  function filtered(){let list=catalog.filter(b=>b.pages<=Number($('#pages').value)&&(!$('#availableOnly').checked||b.available)&&(!$('#ebooks').checked||b.ebook)&&(!$('#genre').value||b.genre===$('#genre').value));if(state.showSaved)list=list.filter(b=>state.saved.has(b.title));if(state.query){const q=state.query.toLowerCase();list=list.filter(b=>[b.title,b.author,b.genre,...b.words].join(' ').toLowerCase().includes(q)||b.words.some(w=>q.split(/\s+/).some(t=>w.includes(t))))}const sort=state.guideMode?'match':$('#sort').value;if(sort==='match')list.sort((a,b)=>score(b)-score(a));if(state.guideMode&&state.aiOrder){const order=new Map(state.aiOrder.map((title,index)=>[title,index]));list.sort((a,b)=>(order.get(a.title)??999)-(order.get(b.title)??999)||score(b)-score(a))}if(sort==='rating')list.sort((a,b)=>b.rating-a.rating);if(sort==='title')list.sort((a,b)=>a.title.localeCompare(b.title));if(sort==='short')list.sort((a,b)=>a.pages-b.pages);if(state.guideMode)list=list.slice(0,3);return list}
