  async function finishGuide(){state.guideMode=true;state.showSaved=false;state.query='';state.moods.clear();$('#search').value='';$('#genre').value='';$('#pages').value=pageFilterMax;$('#pagesLabel').textContent=String(pageFilterMax);$('#availableOnly').checked=false;$('#ebooks').checked=false;document.querySelectorAll('input[name="mood"]').forEach(el=>el.checked=false);$('#sort').value='match';state.guidePreferences={mood:guideAnswers.mood||'',genre:guideAnswers.genre||'',text:guideAnswers.text||''};state.aiOrder=null;render();let picks=filtered();if(activeModel){addBubble('guide',`I’m asking your local ${activeModel} model to rank the matches.`);try{state.aiOrder=await rankWithLocalModel(state.guidePreferences);render();picks=filtered();addBubble('guide',`Your local model ranked these from your answers. The first match is ${picks[0]?.title||'on your shelf'}; I’ve put the top ${picks.length} picks on the page.`)}catch{addBubble('guide','Ollama could not answer this time, so I used the local preference matcher instead.')}}else addBubble('guide','I used the on-device preference matcher. Start Ollama and run this page with python server.py to add local model recommendations.');picks=filtered();const lead=picks[0];if(!activeModel)addBubble('guide',lead?`Start with ${lead.title} by ${lead.author} (${lead.genre}).`:'I couldn’t find a close match in this small sample shelf.');if(lead)guideChoices.innerHTML='<button type="button" class="guide-chip" id="showPicks">Show my picks</button><button type="button" class="guide-chip" id="restartGuide">Start over</button>';else guideChoices.innerHTML='<button type="button" class="guide-chip" id="restartGuide">Try again</button>';guideInput.value='';guideInput.placeholder='';guideInput.disabled=true;$('#guideForm button').disabled=true;}
  function answerGuide(value){const answer=value.trim();if(guideStep===0){guideAnswers.mood=['comfort','thoughtful','page-turner','escape'].includes(answer)?answer:'comfort';addBubble('you',answer||'Surprise me')}else if(guideStep===1){guideAnswers.genre=['Mystery','Literary Fiction','Fantasy','Science Fiction','Memoir','Romance','Historical Fiction','Nonfiction'].includes(answer)?answer:'';addBubble('you',answer||'Surprise me')}else{guideAnswers.text=answer;addBubble('you',answer||'No particular favorite')}guideStep++;guideChoices.innerHTML='';if(guideStep<3)askGuideStep();else void finishGuide()}
