  booksEl.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const title=save.dataset.save;state.saved.has(title)?state.saved.delete(title):state.saved.add(title);localStorage.setItem('stacks-saved',JSON.stringify([...state.saved]));render();toast(state.saved.has(title)?'Saved to your books':'Removed from saved books');return}const vote=e.target.closest('[data-feedback]');if(vote){feedback[vote.dataset.title]=vote.dataset.feedback;localStorage.setItem('stacks-feedback',JSON.stringify(feedback));render();toast(vote.dataset.feedback==='like'?'We’ll look for more books like this':'We’ll show fewer books like this');return}const read=e.target.closest('[data-read]');if(read){const book=catalog.find(item=>item.title===read.dataset.read);void openReader(book);return}const borrow=e.target.closest('[data-borrow]');if(borrow){const book=catalog.find(item=>item.title===borrow.dataset.borrow);if(book?.uploadId||book?.cloudId){void openReader(book);return}toast('Demo only: connect a library catalog to check live availability');return}const details=e.target.closest('[data-details]');if(details){showBookDetails(details.dataset.details);return}});
