  $('#bookCoverImage').addEventListener('change',async e=>{const file=e.target.files?.[0],preview=$('#coverPreview');if(!file){preview.hidden=true;return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){e.target.value='';preview.hidden=true;$('#uploadStatus').textContent='Choose a JPG, PNG, or WebP cover smaller than 5 MB.';return}preview.innerHTML=`<img src="${await fileAsDataUrl(file)}" alt="Selected book cover">`;preview.hidden=false});
  $('#bookUploadForm').addEventListener('submit',async e=>{
    e.preventDefault();
    const status=$('#uploadStatus'),full=$('#fullBookPdf').files?.[0],files=full?[full]:chapterFiles,cover=$('#bookCoverImage').files?.[0];
    if(cloudClient&&!currentUser){status.textContent='Log in first so this book is saved to your account and available on your other devices.';return}
    if(!files.length){status.textContent='Choose one complete book PDF or at least one chapter PDF.';return}
    if(files.length>30){status.textContent='Add up to 30 chapter PDFs at a time.';return}
    if(files.some(file=>!file.name.toLowerCase().endsWith('.pdf'))){status.textContent='Every reading file must be a PDF.';return}
    if(files.reduce((sum,file)=>sum+file.size,0)>150*1024*1024){status.textContent='Keep the combined PDF files under 150 MB.';return}
    if(cover&&cover.size>5*1024*1024){status.textContent='The cover image must be smaller than 5 MB.';return}
    status.textContent='Checking PDFs and uploading to your private library…';$('#bookUploadForm button[type="submit"]').disabled=true;
    try{
      const library=await getPdfLibrary(),pageCounts=[];let totalPages=0;
      for(const file of files){if(await file.slice(0,5).text()!=='%PDF-')throw new Error(`${file.name} is not a valid PDF.`);const loadingTask=library.getDocument({data:new Uint8Array(await file.arrayBuffer())}),pdf=await loadingTask.promise;pageCounts.push(pdf.numPages);totalPages+=pdf.numPages;await loadingTask.destroy()}
      const record={id:crypto.randomUUID(),title:$('#uploadTitle').value.trim(),author:$('#uploadAuthor').value.trim()||'Unknown author',pages:totalPages,isPublished:$('#publishBook').checked};
      if(cloudClient){await saveBookToCloud(record,files,cover,pageCounts);await loadCloudBooks()}else{const pdfs=[];for(const file of files)pdfs.push({name:file.name,file:new Blob([await file.arrayBuffer()],{type:'application/pdf'})});const localRecord={...record,pdfs,coverBlob:cover?new Blob([await cover.arrayBuffer()],{type:cover.type}):null,createdAt:Date.now()};await putUploadedBook(localRecord);uploadedBooks.set(record.id,localRecord);catalog.push(libraryCardForUpload(localRecord,localRecord.coverBlob?await fileAsDataUrl(localRecord.coverBlob):''));updatePageFilterMax();render()}
      $('#bookUploadForm').reset();chapterFiles=[];renderChapterFiles();$('#coverPreview').hidden=true;status.textContent='';$('#addBookModal').close();toast('Book saved to your online library');
    }catch(error){status.textContent=error.message||'Could not upload this book. Check your connection and storage settings.'}
    finally{$('#bookUploadForm button[type="submit"]').disabled=false}
  });
