  function updateAccountButton(){const button=$('#accountButton');button.textContent=currentUser?'Sign out':'Log in';button.title=currentUser?`Signed in as ${currentUser.email}. Click to sign out.`:'Sign in to access your books on every device';$('#migrateBooks').hidden=!currentUser;$('#uploadCloudHint').textContent=cloudClient?(currentUser?'Your PDFs are stored online in your private library. Only you can open or manage them.':'Sign in to store books online and access them from your other devices.'):'Uploads stay in this browser until you configure Supabase in README.md.';render()}
  $('#migrateBooks').addEventListener('click',async()=>{const status=$('#migrateStatus');if(!currentUser||!cloudClient){status.textContent='Log in first to move the saved files into your online account.';return}const local=await getUploadedBooks();if(!local.length){status.textContent='No older browser-saved books were found.';return}const button=$('#migrateBooks');button.disabled=true;try{const library=await getPdfLibrary();for(const book of local){const files=[],counts=[];let pages=0;for(const chapter of book.pdfs){const file=new File([chapter.file],chapter.name,{type:'application/pdf'}),task=library.getDocument({data:new Uint8Array(await file.arrayBuffer())}),pdf=await task.promise;counts.push(pdf.numPages);pages+=pdf.numPages;await task.destroy();files.push(file)}const cover=book.coverBlob?new File([book.coverBlob],`cover-${book.id}.jpg`,{type:book.coverBlob.type||'image/jpeg'}):null;await saveBookToCloud({id:book.id,title:book.title,author:book.author||'Unknown author',pages,isPublished:false},files,cover,counts);await deleteUploadedBook(book.id);uploadedBooks.delete(book.id);const index=catalog.findIndex(item=>item.uploadId===book.id);if(index>=0)catalog.splice(index,1)}await loadCloudBooks();status.textContent=`Moved ${local.length} saved book${local.length===1?'':'s'} into your private online library.`;render()}catch(error){status.textContent=error.message||'Could not move the saved books. Any books already moved are in your online library.'}finally{button.disabled=false}});
